using System;using System.Collections.Generic;using System.Drawing;using System.IO;using System.Linq;using System.Windows.Forms;using System.Xml.Serialization;
namespace ShotOut {partial class Editor {
public void VerifyProjectSearch(List<string> report,string folder){
Action<bool,string> check=(ok,label)=>{if(!ok)throw new Exception(label);report.Add("PASS "+label);};string oldFolder=Preferences.Current.ScreenshotFolder,oldRoot=ProjectHistory.TestFolder,oldProjectFolder=Preferences.Current.ProjectFolder;try{
var bindings=new Preferences();bindings.Capture[0].Chord=(int)(Keys.Control|Keys.K);bool reserved=false;try{bindings.Validate();}catch(ArgumentException){reserved=true;}check(reserved,"Ctrl+K cannot be assigned to a global capture hotkey");string legacy=Path.Combine(folder,"legacy-search-hotkey.xml");using(var stream=File.Create(legacy))new XmlSerializer(typeof(Preferences)).Serialize(stream,bindings);var migrated=Preferences.Read(legacy);check(migrated.Capture[0].Chord==new Preferences().Capture[0].Chord,"Existing capture bindings that used Ctrl+K migrate to their normal shortcut");string data=Path.Combine(folder,"library-fixture");Directory.CreateDirectory(data);ProjectHistory.TestFolder=Path.Combine(folder,"recent-projects");ProjectHistory.Reset();Preferences.Current.ScreenshotFolder=data;Preferences.Current.ProjectFolder=data;LoadBitmap(Blank(320,200),"Search fixture");var label=new Mark {Kind="Text",Name="Release label",Text="Deployment instructions for database",X=20,Y=20,W=250,H=50,Color=Color.DarkRed.ToArgb()};Marks.Add(label);RefreshImage();string project=Path.Combine(data,"Deployment.shotout");using(var stream=File.Create(project))new XmlSerializer(typeof(Project)).Serialize(stream,Snapshot());RecordRecentProject(project);check(ProjectHistory.Current.Items.Count==1&&File.Exists(ProjectHistory.ThumbnailPath(project)),"Opening or saving a project records a small recent-project thumbnail");RecordRecentProject(project);check(ProjectHistory.Current.Items.Count==1,"Recent projects deduplicate repeated opens");ProjectHistory.Reset();check(ProjectHistory.Current.Items.Count==1&&ProjectHistory.Current.Items[0].Path==project,"Recent project paths persist across sessions");
using(var thumb=CreateScreenshotThumbnail(project))check(thumb.Size==new Size(144,100),"Project browser uses a bounded cached thumbnail");using(var image=Blank(20,20))image.Save(Path.Combine(data,"Example.png"));File.WriteAllText(Path.Combine(data,"ignored.txt"),"ignore");Directory.CreateDirectory(Path.Combine(data,"Folder"));var recent=ProjectHistory.Current.Items.ToArray();var images=ReadLibraryEntries(data,0,false,"Name A–Z",recent);var projects=ReadLibraryEntries(data,0,true,"Newest",recent);check(images.Any(path=>path.EndsWith("Example.png"))&&!images.Contains(project)&&projects.Contains(project)&&!projects.Any(path=>path.EndsWith("Example.png")),"Images and Projects tabs filter their own file types while retaining folders");
string external=Path.Combine(folder,"External.shotout");File.Copy(project,external,true);RecordRecentProject(external);check(ReadLibraryEntries(data,0,true,"Newest",ProjectHistory.Current.Items.ToArray()).Contains(external),"Recent projects remain discoverable outside the screenshot folder");string beta=Path.Combine(data,"Beta.png"),alpha=Path.Combine(data,"Alpha.png");using(var image=Blank(12,12)){image.Save(beta);image.Save(alpha);}var names=ReadLibraryEntries(data,0,false,"Name A–Z",recent).Where(File.Exists).Select(Path.GetFileName).ToArray();check(names[0]=="Alpha.png"&&names[1]=="Beta.png","Library name sorting orders files consistently");
StoreDocument();var entries=CaptureSearchEntries();var matches=QuickSearchDialog.Filter(entries,"database");check(matches.Any(entry=>entry.Mark==label),"Quick search finds annotation text without decoding image data");check(QuickSearchDialog.Filter(entries,"Release label").Any(entry=>entry.Mark==label),"Quick search finds renamed annotations");int sourceTab=currentDocument;AddWelcomeDocument();OpenSearchEntry(matches.First(entry=>entry.Mark==label));check(currentDocument==sourceTab&&Active==label&&Selected.Contains(label),"Choosing an annotation search result activates its tab and selects the object");check(label.Text=="Deployment instructions for database","Search navigation leaves annotation content intact");
var message=Message.Create(Handle,0,IntPtr.Zero,IntPtr.Zero);using(var timer=new Timer {Interval=40}){timer.Tick+=delegate{timer.Stop();var dialog=Application.OpenForms.OfType<QuickSearchDialog>().FirstOrDefault();if(dialog!=null)dialog.Close();};timer.Start();check(ProcessCmdKey(ref message,Keys.Control|Keys.K),"Ctrl+K opens search from the editor");}
Show();Application.DoEvents();using(var search=new QuickSearchDialog(entries,data,ProjectHistory.Current.Items.ToArray(),entry=>{})){search.Show(this);search.Query.Text="database";var until=DateTime.UtcNow.AddSeconds(3);while(search.Results.Items.Count==0&&DateTime.UtcNow<until){Application.DoEvents();System.Threading.Thread.Sleep(10);}check(search.Results.Items.Cast<QuickSearchEntry>().Any(entry=>entry.Mark==label),"Search popup debounces input and displays matching annotations");using(var screenshot=new Bitmap(search.Width,search.Height)){search.DrawToBitmap(screenshot,new Rectangle(Point.Empty,screenshot.Size));screenshot.Save(Path.Combine(folder,"quick-search.png"));}search.Query.Text="Deployment.shotout";until=DateTime.UtcNow.AddSeconds(3);while(!search.Results.Items.Cast<QuickSearchEntry>().Any(entry=>entry.Path==project)&&DateTime.UtcNow<until){Application.DoEvents();System.Threading.Thread.Sleep(10);}check(search.Results.Items.Cast<QuickSearchEntry>().Any(entry=>entry.Path==project),"Quick search discovers saved project filenames asynchronously");search.Close();}
AddWelcomeDocument();screenshotBrowsing=data;SetLibraryType(true);Application.DoEvents();check(projectsLibraryButton.Selected&&!imagesLibraryButton.Selected&&screenshotFiles.Items.Cast<ListViewItem>().Any(item=>item.Tag as string==project),"Projects tab displays recent and folder projects");using(var screenshot=new Bitmap(Width,Height)){DrawToBitmap(screenshot,new Rectangle(Point.Empty,screenshot.Size));screenshot.Save(Path.Combine(folder,"projects-library.png"));}
