}finally{Preferences.Current.ScreenshotFolder=oldFolder;Preferences.Current.ProjectFolder=oldProjectFolder;ProjectHistory.TestFolder=oldRoot;ProjectHistory.Reset();projectLibrary=false;if(imagesLibraryButton!=null){imagesLibraryButton.Selected=true;projectsLibraryButton.Selected=false;}LoadBitmap(Blank(100,100),"Test");}
}
